请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-105

=== 用户原始指令 (query.txt) ===
搞个内存清理的图呢，点一下能进系统操作，能从日历读日程

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个内存清理的图呢，点一下能进系统操作，能从日历读日程",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModel": {
    "value": {
      "memory": {
        "title": "内存清理",
        "status": "可释放 1.8GB",
        "actionText": "去清理"
      },
      "assets": {
        "clearIcon": "resources/base/media/icon_clear.png"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "mock-calendar-105-1",
              "title": "15:30 项目同步",
              "dtStart": "15:30",
              "dtEnd": "16:00"
            }
          ]
        }
      },
      "state": {
        "calendarLabel": "下一程"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "clear_icon",
      "src": "resources/base/media/icon_clear.png",
      "use": "memory clean illustration",
      "description": "手机状态清理场景的清除图标，适合做内存清理主视觉。",
      "bindTo": "/assets/clearIcon",
      "static": true
    }
  ]
}

